<script setup>
import { fontWeights,weightNames,textMarkCss } from '../textStyles.js';
import { fontCss, fonts } from '../fonts.js';
const props=defineProps({value:Object,font:String,type:String});const emit=defineEmits(['change']);
function color(e,commit=false){if(/^#[\da-f]{6}$/i.test(e.target.value))emit('change','highlightColor',e.target.value);else if(commit)e.target.value=props.value.highlightColor;}
</script>
<template><div class="text-styles"><label>Graisse<select :value="value.weight" aria-label="Graisse du texte" @change="emit('change','weight',Number($event.target.value))"><option v-for="weight in fontWeights(font,type)" :key="weight" :value="weight">{{weight}} · {{weightNames[weight]}}</option></select></label><div class="text-style-buttons"><button v-for="[key,label,icon] in [['italic','Italique','I'],['underline','Souligné','S'],['strike','Barré','B'],['highlight','Surligné','▰']]" :key="key" :class="[key,{active:value[key]}]" :aria-label="label" :aria-pressed="value[key]" :title="label" @click="emit('change',key,!value[key])">{{icon}}</button></div><p v-if="value.italic&&fonts.find(f=>f.id===font)?.italic===false" class="field-help">Cette police utilise une inclinaison synthétique.</p><template v-if="value.highlight"><label>Couleur du surlignage<div class="shape-color"><input type="color" :value="value.highlightColor" aria-label="Couleur du surlignage" @input="emit('change','highlightColor',$event.target.value)"><input type="text" :value="value.highlightColor" aria-label="Surlignage hexadécimal" maxlength="7" @input="color" @change="color($event,true)"></div></label><label>Intensité · {{value.highlightOpacity}} %<input type="range" :value="value.highlightOpacity" min="0" max="100" aria-label="Intensité du surlignage" @input="emit('change','highlightOpacity',Number($event.target.value))"></label></template><p class="text-style-preview" :style="{fontFamily:fontCss(font,type),fontWeight:value.weight,fontStyle:value.italic?'italic':'normal',fontSynthesis:'style'}"><span :style="textMarkCss(value)">Java · Écrire et comprendre.</span></p><button class="btn full" @click="emit('change','reset')">Réinitialiser le style</button><p class="field-help">Appliqué à tout le bloc sélectionné.</p></div></template>
